211	        key: Str,
212	        /// A default value to return if the key is not part of the dictionary.
213	        #[named]
214	        default: Option<Value>,
215	    ) -> StrResult<Value> {
216	        self.0
217	            .get(&key)
218	            .cloned()
219	            .or(default)
220	            .ok_or_else(|| missing_key_no_default(&key))
